using System.Globalization;using System.Windows;using WPF_SEMANA02.Data;using WPF_SEMANA02.Models;
namespace WPF_SEMANA02.Views;
public partial class CamionesWindow:Window{public CamionesWindow(){InitializeComponent();dgCamiones.ItemsSource=AppData.Camiones;}private void Guardar_Click(object s,RoutedEventArgs e){if(string.IsNullOrWhiteSpace(txtPlaca.Text)||!double.TryParse(txtPesoMaximo.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var max)||!double.TryParse(txtPesoVacio.Text,NumberStyles.Any,CultureInfo.CurrentCulture,out var vacio)){MessageBox.Show("Complete los campos con valores válidos.","Validación");return;}AppData.Camiones.Add(new Camion{Placa=txtPlaca.Text.Trim().ToUpper(),PesoMaximo=max,PesoVacio=vacio});MessageBox.Show("Camión registrado correctamente.","Información");Limpiar();}private void Nuevo_Click(object s,RoutedEventArgs e)=>Limpiar();private void Limpiar_Click(object s,RoutedEventArgs e)=>Limpiar();private void Limpiar(){txtPlaca.Clear();txtPesoMaximo.Clear();txtPesoVacio.Clear();txtPlaca.Focus();}private void Volver_Click(object s,RoutedEventArgs e)=>Close();}
